import{_ as i,o as a,c as r,a3 as l,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/unterricht-kataloge/kataloge-schulen-nrw.png",p=JSON.parse('{"title":"Benötigte Schulen in NRW in den Katalog aufnehmen","description":"","frontmatter":{"title":"Benötigte Schulen in NRW in den Katalog aufnehmen","source_pageid":338,"source_revision":5426},"headers":[],"relativePath":"schild3/unterricht-kataloge/schulen-in-nrw-allgemeine-kataloge.md","filePath":"schild3/unterricht-kataloge/schulen-in-nrw-allgemeine-kataloge.md"}'),h={name:"schild3/unterricht-kataloge/schulen-in-nrw-allgemeine-kataloge.md"};function c(o,t,s,d,g,m){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="benotigte-schulen-in-nrw-in-den-katalog-aufnehmen" tabindex="-1">Benötigte Schulen in NRW in den Katalog aufnehmen <a class="header-anchor" href="#benotigte-schulen-in-nrw-in-den-katalog-aufnehmen" aria-label="Permalink to &quot;Benötigte Schulen in NRW in den Katalog aufnehmen&quot;">​</a></h1><p>Übernehmen Sie die für Ihre Schule benötigten NRW-Schulen aus dem bereitgestellten Schulverzeichnis und legen Sie die gewünschte Reihenfolge fest.</p><p><a href="/bilder/unterricht-kataloge/kataloge-schulen-nrw.png"><img src="'+u+'" alt="Karteireiter Kataloge ➜ Schulen NRW. Hier soll z.B. eine Schule aus Münster gesucht werden." loading="lazy"></a></p><p><em>Karteireiter Kataloge ➜ Schulen NRW. Hier soll z.B. eine Schule aus Münster gesucht werden.</em></p><p>Über diesen Katalog wird eine Liste der Schulen aus NRW erstellt, die nach den schulspezifischen Bedürfnissen ausgewählt und sortiert angezeigt werden kann.</p><p>Der Katalog enthält die Schulen, die Ihre Schule für die Datenpflege benötigt. Dazu gehören häufig Nachbarschulen und Schulen im Einzugsbereich. Auch frühere Aufnahmen, Abgänge oder Abordnungen von Lehrkräften können einen Eintrag erforderlich machen.</p><p>Die Sortierung kann oben über <em>Sortierung</em> gewählt werden (Bezeichnung, PLZ, Ort, Schulnummer oder benutzerdefiniert).</p><p>Klicken Sie auf <strong>+</strong>, um die Liste aller Schulen in NRW zu öffnen. Suchen Sie nach Schulnummer, Name, Ort oder Postleitzahl und übernehmen Sie die gewünschte Schule.</p>',8),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,[n("Beim Nutzen dieser Filterbedingung und nach Eingabe eines Ortes, Schulnummer o.ä. bitte nicht unten auf den Button "),e("em",null,"Übernehmen"),n(" klicken, sondern auf den roten Haken neben den Eingabefeldern. Danach die Schule auswählen und dann mit "),e("em",null,"Übernehmen"),n(" dem Katalog hinzufügen.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schulen_in_NRW_(Allgemeine_Kataloge)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5426.")],-1)])])}const S=i(h,[["render",c]]);export{p as __pageData,S as default};
